BEGIN;
CREATE TABLE pantry.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200),unit_code text NOT NULL REFERENCES core.units(code),low_stock_threshold numeric(18,6) CHECK(low_stock_threshold>=0),integer_quantities boolean NOT NULL DEFAULT false,barcode text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',archived_at timestamptz,created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id));
CREATE TABLE pantry.locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),sort_order bigint NOT NULL DEFAULT 0,archived_at timestamptz,created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),UNIQUE(household_id,name));
CREATE TABLE pantry.lots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),product_id uuid NOT NULL,location_id uuid NOT NULL,received_on date NOT NULL,best_before_on date,use_by_on date,opened_on date,notes text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),FOREIGN KEY(household_id,product_id) REFERENCES pantry.products(household_id,id),FOREIGN KEY(household_id,location_id) REFERENCES pantry.locations(household_id,id));
CREATE INDEX lots_expiry ON pantry.lots(household_id,use_by_on,best_before_on);
CREATE TABLE pantry.stock_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),lot_id uuid NOT NULL,quantity_delta numeric(18,6) NOT NULL CHECK(quantity_delta<>0),reason text NOT NULL CHECK(reason IN('receive','consume','waste','adjust','transfer','reversal')),correlation_id uuid,reverses_movement_id uuid UNIQUE REFERENCES pantry.stock_movements(id),note text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),FOREIGN KEY(household_id,lot_id) REFERENCES pantry.lots(household_id,id));
CREATE INDEX movements_lot ON pantry.stock_movements(household_id,lot_id,created_at);
CREATE TRIGGER movements_immutable BEFORE UPDATE OR DELETE ON pantry.stock_movements FOR EACH ROW EXECUTE FUNCTION core.reject_mutation();
GRANT USAGE ON SCHEMA pantry TO household_app; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA pantry TO household_app;
REVOKE UPDATE,DELETE ON pantry.stock_movements FROM household_app;
COMMIT;
